def log_execution(func):
    def wrapper(*args, **kwargs):
        print(f"Running '{func.__name__}'...")
        result = func(*args, **kwargs)
        print(f"Finished '{func.__name__}'")
        return result
    return wrapper


@log_execution
def add(a, b):
    return a + b


print("Result:", add(3, 4))
